# services/ingestion_pipeline.py
import os
import hashlib
import pdfplumber
from PIL import Image
import pytesseract
from io import BytesIO
from models import Document, DocumentMetadata, DocumentVersion
from database import SessionLocal
from datetime import datetime
from utils.ocr import process_scanned_document
from utils.classifier import classify_license
from utils.validator import validate_citations

def calculate_checksum(data):
    return hashlib.sha256(data).hexdigest()

def extract_text_from_pdf(pdf_path):
    text = ""
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            text += page.extract_text()
    return text

def process_document(source_url, document_type, source_tier):
    try:
        # Download document logic here
        raw_data = download_document(source_url)
        checksum = calculate_checksum(raw_data)
        
        # Check for duplicates
        if document_exists(checksum):
            return {"status": "duplicate", "checksum": checksum}
            
        # Extract metadata
        metadata = extract_metadata(source_url, document_type)
        
        # Classify license
        license_class = classify_license(source_url, metadata)
        
        # Process text
        text = None
        if document_type in [DocumentType.constitution, DocumentType.legislation]:
            if is_scanned(raw_data):
                text = process_scanned_document(raw_data)
            else:
                text = extract_text_from_pdf(BytesIO(raw_data))
        
        # Validate citations
        citation_errors = validate_citations(text, metadata.citation)
        
        # Create document record
        db = SessionLocal()
        document = Document(
            source_type=document_type,
            source_tier=source_tier,
            license_class=license_class,
            source_url=source_url,
            checksum=checksum
        )
        db.add(document)
        db.commit()
        
        metadata_record = DocumentMetadata(
            document_id=document.id,
            citation=metadata.citation,
            effective_date=metadata.effective_date,
            amendment_history=metadata.amendment_history,
            source_specific_id=metadata.source_specific_id
        )
        db.add(metadata_record)
        
        version = DocumentVersion(
            document_id=document.id,
            version_number=1,
            full_text=text if license_class in [LicenseClass.public_domain, LicenseClass.open_license, LicenseClass.official] else None,
            hash=checksum,
            effective_date=datetime.utcnow(),
            is_current=True
        )
        db.add(version)
        db.commit()
        db.close()
        
        return {
            "status": "queued_for_approval",
            "document_id": document.id,
            "citation_errors": citation_errors
        }
        
    except Exception as e:
        log_error(e)
        return {"status": "failed", "error": str(e)}

# services/approval_workflow.py
from flask import Blueprint, request, jsonify
from models import Document, DocumentMetadata
from database import SessionLocal
from auth import requires_operator

approval_bp = Blueprint('approval', __name__)

@approval_bp.route('/api/legal/approve', methods=['POST'])
@requires_operator
def approve_document():
    data = request.json
    db = SessionLocal()
    document = db.query(Document).get(data['document_id'])
    
    if not document:
        return jsonify({"error": "Document not found"}), 404
    
    document.approval_status = "approved"
    document.approved_by = data['operator_id']
    document.approval_timestamp = datetime.utcnow()
    
    db.commit()
    db.close()
    return jsonify({"status": "approved", "document_id": document.id})

@approval_bp.route('/api/legal/review', methods=['GET'])
def get_pending_reviews():
    db = SessionLocal()
    pending = db.query(Document).filter_by(approval_status="pending").all()
    results = [{
        "id": d.id,
        "source_type": d.source_type.value,
        "citation": d.metadata.citation,
        "license_class": d.license_class.value
    } for d in pending]
    db.close()
    return jsonify(results)

# tests/test_legal_knowledge.py
import pytest
from models import Document, DocumentMetadata, DocumentVersion
from services.ingestion_pipeline import process_document, document_exists
from services.approval_workflow import approve_document
from database import SessionLocal, engine
from datetime import datetime

def test_document_versioning():
    db = SessionLocal()
    doc = Document(
        source_type=DocumentType.constitution,
        source_tier=DocumentSourceTier.tier1,
        license_class=LicenseClass.public_domain,
        source_url="http://example.com/constitution",
        checksum="test-checksum"
    )
    db.add(doc)
    db.commit()
    
    metadata = DocumentMetadata(
        document_id=doc.id,
        citation="Constitution Art. 12",
        effective_date=datetime(1992, 12, 29)
    )
    db.add(metadata)
    
    version1 = DocumentVersion(
        document_id=doc.id,
        version_number=1,
        full_text="Original text",
        hash="hash1",
        effective_date=datetime(1992, 12, 29),
        is_current=True
    )
    db.add(version1)
    
    version2 = DocumentVersion(
        document_id=doc.id,
        version_number=2,
        full_text="Amended text",
        hash="hash2",
        effective_date=datetime(2023, 1, 1),
        is_current=True
    )
    db.add(version2)
    
    db.commit()
    db.close()
    
    # Verify version history
    db = SessionLocal()
    doc = db.query(Document).get(doc.id)
    assert len(doc.versions) == 2
    assert doc.versions[0].is_current is False
    assert doc.versions[1].is_current is True
    db.close()

def test_copyright_restriction():
    db = SessionLocal()
    doc = Document(
        source_type=DocumentType.legislation,
        source_tier=DocumentSourceTier.tier1,
        license_class=LicenseClass.copyright,
        source_url="http://example.com/act896",
        checksum="copyright-test"
    )
    db.add(doc)
    db.commit()
    
    # Should not store full text
    version = DocumentVersion(
        document_id=doc.id,
        version_number=1,
        full_text=None,
        hash="hash3",
        effective_date=datetime(2023, 1, 1)
    )
    db.add(version)
    db.commit()
    
    doc = db.query(Document).get(doc.id)
    assert doc.versions[0].full_text is None
    db.close()

