# utils/classifier.py
def classify_license(source_url, metadata):
    if "ghanagazette.gov.gh" in source_url or source_url.startswith("https://www.ghanajudiciary.gov.gh"):
        return LicenseClass.official
    elif "universityofghana.edu" in source_url and metadata.get("open_access"):
        return LicenseClass.open_license
    elif "copyright" in metadata.get("disclaimer", "").lower():
        return LicenseClass.copyright
    else:
        return LicenseClass.unknown

# utils/validator.py
import re

def validate_citations(text, expected_citation):
    errors = []
    
    # Check for standard legal citations
    if not re.search(r'[A-Z][a-z]+ (Art\.|Sec\.|s\.|§) \d+', text):
        errors.append("Missing standard citation format")
    
    # Check for case law citations
    if expected_citation.startswith("Case "):
        if not re.search(r'\b\d{4} GLLR \d+\b', text):
            errors.append("Missing case report citation")
    
    # Check for legislative instruments
    if "LI" in expected_citation:
        if not re.search(r'LI \d{4}/\d+', text):
            errors.append("Missing legislative instrument citation")
    
    return errors